/**
 * Who gets the lead, and how loudly.
 *
 * Every escalating rule in the keyword table assumes a human picks it up.
 * Until this existed, "escalate: true" meant a flag on an object and nothing
 * else -- the buyer was told someone would come back to them and nobody was
 * told to. This is the piece that makes that promise true.
 *
 * Lagos is UTC+1 year-round (no daylight saving), so the roster is computed
 * from a fixed offset rather than the server's clock, which runs UTC in
 * Manchester.
 */


const LAGOS_OFFSET_MINUTES = 60;

/** Day-of-week and hour in Lagos, from any UTC instant. */
function lagosTime(nowMs) {
  const d = new Date(nowMs + LAGOS_OFFSET_MINUTES * 60 * 1000);
  return { dow: d.getUTCDay(), hour: d.getUTCHours(), minute: d.getUTCMinutes(),
           iso: d.toISOString().replace('T', ' ').slice(0, 16) + ' WAT' };
}

/**
 * Rules come from the client's own signed roster, not from us:
 *   primary   Mon-Fri 08:00-20:00
 *   secondary weekends and evening cover
 *   supervisor overrides -- used when a lead has gone unclaimed
 */
function onDuty(escalation, nowMs, opts) {
  const o = opts || {};
  const esc = escalation || {};
  const t = lagosTime(nowMs == null ? Date.now() : nowMs);
  const weekend = t.dow === 0 || t.dow === 6;
  const inHours = t.hour >= 8 && t.hour < 20;

  if (o.unclaimed && esc.supervisor) {
    return { ...esc.supervisor, role: 'supervisor', why: 'lead unclaimed past the alert window', lagos_time: t.iso };
  }
  if (!weekend && inHours && esc.primary) {
    return { ...esc.primary, role: 'primary', why: 'weekday business hours', lagos_time: t.iso };
  }
  if (esc.secondary) {
    return { ...esc.secondary, role: 'secondary', why: weekend ? 'weekend cover' : 'evening cover', lagos_time: t.iso };
  }
  return { ...(esc.primary || {}), role: 'primary', why: 'no cover configured — falling back to primary', lagos_time: t.iso };
}

/**
 * Hot means the buyer has signalled money or a visit. It is the difference
 * between "someone should see this today" and "someone must see this now",
 * and it is what justifies paying for an SMS rather than sending an email.
 */
const HOT_RULES = new Set([
  'SP-ESC-PAYTO',   // ready to pay
  'SP-INSPECT',     // wants to come and see it
  'SP-VIRTUAL',     // diaspora, wants a call booked
  'SP-ESC-REFUND',  // trust moment -- a slow reply here costs the deal
  'SP-ESC-LEGAL',   // trust moment
  'SP-INVEST',      // sizing a position
  'SP-DEVPLOT'      // bulk buyer
]);

function isHot(o) {
  const x = o || {};
  if (x.rule_id && HOT_RULES.has(x.rule_id)) return true;
  // The brain escalated something the keyword table never saw. Treat an
  // unknown escalation as hot: the cost of over-alerting is an SMS, the cost
  // of under-alerting is a buyer who waited.
  return x.escalate === true && !x.rule_id;
}

/** The message a human actually reads on their phone. */
function buildAlert(o) {
  const x = o || {};
  const who = x.on_duty || {};
  const lines = [
    `${isHot(x) ? '🔴 HOT' : '🟡'} Instagram lead — ${x.client_name || x.client_id || 'client'}`,
    '',
    `From:      @${x.contact_handle || x.contact_id || 'unknown'}`,
    `Channel:   ${x.channel === 'instagram_comment' ? 'comment on a post' : 'direct message'}`,
    `They said: ${(x.text || '').slice(0, 200)}`,
    `Matched:   ${x.rule_id || 'no keyword — the assistant handled it'}${x.intent ? ' (' + x.intent + ')' : ''}`,
    `Reason:    ${x.escalation_reason || 'needs a human'}`,
    ''
  ];
  if (x.reply) lines.push('The assistant already sent them:', '"' + String(x.reply).split('\n')[0] + '"', '');
  lines.push(`Assigned:  ${who.name || 'unassigned'} (${who.role || '-'}, ${who.why || '-'})`,
             `Reply within ${x.alert_minutes || 15} minutes.`,
             '',
             `Open the Instagram inbox and search @${x.contact_handle || ''}`);
  return lines.join('\n');
}



const REGISTRY = {"clients":{"shalom-park":{"name":"Shalom Park Estate","escalation":{"primary":{"name":"Collins","whatsapp":"2348064834680","hours":"Mon-Fri 08:00-20:00"},"secondary":{"name":"Mercy","whatsapp":"2349035508012","hours":"Weekends / evenings"},"supervisor":{"name":"Tobi","whatsapp":"2347035461661","hours":"Overrides"},"unclaimed_alert_minutes":15},"alerts":{"email_to":["sales@shalomparknigeria.com"],"email_cc":["aadamola@gmail.com"],"from":"alerts@getpropel.tech","sms_provider":null,"_ruling":"Email is the interim alert channel. It is HONESTLY WEAKER than a WhatsApp ping — a sales inbox gets checked, a phone buzzes. Stripping the WhatsApp API is what removed the strong option, and that is a real cost of the Instagram-only decision, not a detail. Upgrade path: a Nigerian SMS gateway (Termii / Africa's Talking) at roughly ₦4 a message — at 20 leads a day that is about ₦2,400/month, far inside the docs/07 tooling gate. Set sms_provider and the notifier sends hot leads by SMS and the rest by email.","_from_ruling":"Alerts send from alerts@getpropel.tech — a PROPEL-owned mailbox. Never the client's domain (@shalomparknigeria.com) and not a personal address: both erase Propel from the from-line, which is the point. Every alert is a receipt — 20 a day landing in their sales inbox saying 'your assistant found you a buyer' is the drumbeat the commission conversation rests on. Their mailbox is also revocable infrastructure, and sending AS their domain fails SPF/DKIM without their credentials. Set this up BEFORE go-live: changing a sender once alerts are flowing means the first ones from the new address can land in spam, and a missed lead alert is the failure this layer exists to prevent. SMTP host and port come from the Hostinger panel when the mailbox is created."}},"propel":{"name":"Propel","escalation":{"primary":{"name":"Adedamola","whatsapp":"2349019120968","hours":"Business hours"},"unclaimed_alert_minutes":30},"alerts":null}}};

const inp = $input.first().json;
const client = REGISTRY.clients[inp.client_id] || {};
const esc = client.escalation || {};
const who = onDuty(esc, Date.now(), { unclaimed: false });

const notify = inp.escalate === true || inp.send === false;
const hot = isHot({ rule_id: inp.rule_id, escalate: inp.escalate });

const payload = {
  rule_id:      inp.rule_id || '',
  matched:      inp.matched_phrase || '',
  intent:       inp.intent || '',
  channel:      inp.channel,
  handle:       inp.contact_handle || '',
  text:         String(inp.text || '').slice(0, 500),
  reply_sent:   String(inp.reply || '').slice(0, 500),
  escalate:     inp.escalate === true,
  hot,
  held_reason:  inp.reason || '',
  guard:        inp.guard_triggered || '',
  grounded_in:  inp.grounded_in || [],
  link_code:    inp.link_code || '',
  assigned_to:  who.name || '',
  lagos_time:   who.lagos_time
};

const alert = buildAlert({
  client_id: inp.client_id, client_name: client.name,
  contact_handle: inp.contact_handle, contact_id: inp.contact_id,
  channel: inp.channel, text: inp.text, rule_id: inp.rule_id, intent: inp.intent,
  escalation_reason: inp.escalation_reason, reply: inp.reply,
  on_duty: who, alert_minutes: esc.unclaimed_alert_minutes || 15, escalate: inp.escalate
});

return [{ json: {
  ...inp,
  notify, hot,
  event_type: inp.escalate === true ? 'escalation' : 'qualified',
  assigned_sales_rep: who.name || '',
  on_duty: who,
  payload_json: JSON.stringify(payload),
  alert_subject: (hot ? '[HOT] ' : '') + 'Instagram lead — ' + (client.name || inp.client_id) + ' — @' + (inp.contact_handle || inp.contact_id || ''),
  alert_body: alert
}}];

